const fs = require('fs');
const NL = String.fromCharCode(10);
const base = '/vault/Ofertas';
const dirs = ['02_Postuladas','01_Inbox'];
const today = new Date(); today.setHours(0,0,0,0);
const SQ = String.fromCharCode(39);
const parseFM = (txt) => { const m = {}; const a = txt.indexOf('---'); if (a<0) return m; const b = txt.indexOf('---', a+3); if (b<0) return m; const block = txt.slice(a+3, b); for (const line of block.split(NL)) { const i = line.indexOf(':'); if (i<0) continue; const k = line.slice(0,i).trim(); let v = line.slice(i+1).trim(); if (v.length>=2 && v.charCodeAt(0)===39 && v.charCodeAt(v.length-1)===39) v = v.slice(1,-1); m[k]=v; } return m; };
const walk = (d) => { let out=[]; let items=[]; try{ items=fs.readdirSync(d,{withFileTypes:true}); }catch(e){ return out; } for(const it of items){ const p=d+'/'+it.name; if(it.isDirectory()) out=out.concat(walk(p)); else if(it.name==='_Oferta.md') out.push(p); } return out; };
const files = [];
for (const dd of dirs) files.push.apply(files, walk(base+'/'+dd));
const days = (s) => { if(!s) return null; const d=new Date(String(s).trim()+'T00:00:00'); if(isNaN(d.getTime())) return null; return Math.round((d-today)/86400000); };
const alerts = [];
for (const f of files) { let txt=''; try{ txt=fs.readFileSync(f,'utf8'); }catch(e){ continue; } const fm = parseFM(txt); const emp = fm.empresa||'?'; const pue = fm.puesto||'?'; const de = days(fm.fecha_entrevista); if (de!==null && de>=0 && de<=1) alerts.push((de===0?'ENTREVISTA HOY':'ENTREVISTA MANANA')+': '+emp+' - '+pue); const dp = days(fm.fecha_proxima); if (dp!==null && dp<=0 && (fm.proxima_accion||'')) alerts.push('PENDIENTE: '+fm.proxima_accion+' - '+emp); const dpost = days(fm.fecha_postulacion); if ((fm.estado||'')==='postulada' && dpost!==null && dpost<=-7 && !(fm.fecha_respuesta||'') && !(fm.fecha_proxima||'')) alerts.push('SIN RESPUESTA '+Math.abs(dpost)+' dias: '+emp+' ('+pue+') - seguimiento?'); }
if (!alerts.length) return [];
const text = 'Recordatorios de candidaturas'+NL+NL+alerts.join(NL);
return [{ json: { text: text } }];
